package com.trampolim.api.observatory;
import java.util.*;
public final class MetricDefinitions {
 private MetricDefinitions(){}
 private static Map<String,String> metric(String id,String unit,String formula,String clock,String geography,String privacy){return Map.of("id",id,"unit",unit,"formula",formula,"timeBasis",clock,"geographicBasis",geography,"privacy",privacy);}
 public static Map<String,Object> all(){return Map.of("metricsVersion",2,"scope","Somente dados registrados na Trampolim. Não são estatísticas oficiais nem extrapolação do mercado regional.","metrics",List.of(
 metric("registeredPublications","anúncios","COUNT de anúncios job com primeira marca em career_listing_publications, empresa atualmente aprovada e estágio atualmente pago. Não usa headcount.","Mês da primeira marca de publicação, não criação; a marca não comprova sozinha o instante de efetiva elegibilidade pública de estágio.","Código IBGE válido do anúncio; sem código apenas UF-base empresarial.","Agregado de dados empresariais já publicados; contagem exata."),
 metric("active_listings","anúncios","Predicado público de vagas existente: PUBLISHED, empresa aprovada, prazos abertos e estágio PAID.","Estoque no instante da captura, independente do período solicitado.","Município do anúncio; ausência de código é qualidade explícita.","Contagem exata de dados públicos."),
 metric("participatingCompanies","empresas distintas","COUNT DISTINCT company_id com ao menos uma primeira marca válida de publicação no período e território. Não somar valores por município.","Período das primeiras marcas selecionadas.","Território dos anúncios, não sede ou residência do candidato.","IDs empresariais permanecem internos."),
 metric("APPLICATIONS","registros de candidatura","COUNT de company_applications ligadas a vagas job e empresas aprovadas; não representa pessoas únicas.","Mês de created_at da candidatura.","Somente UF do anúncio ou UF-base empresarial.","Administração global; pelo menos dez e-mails distintos normalizados e três empresas; faixa de dez."),
 metric("INTERVIEWS_REPORTED_HELD","relatos de entrevista realizada","COUNT de outcomes com interview_held=TRUE e interview_at passado; relato da empresa, não confirmação independente.","Mês do horário informado para a entrevista.","Somente UF.","Administração global, mesmo limiar e faixas das candidaturas."),
 metric("CONFIRMED_HIRES","confirmações de contratação","COUNT de outcomes com hire_date, confirmação autenticada do candidato e public_metrics_consent=TRUE. Não prova vínculo legal nem inclui relatos não confirmados.","Mês de candidate_confirmed_at, não mês de admissão.","Somente UF; nenhuma divulgação municipal de métricas pessoais.","Dez e-mails de candidatura distintos e três empresas; faixa de dez por mês fixo, sem total pessoal combinável."),
 metric("COURSE_COMPLETIONS","pares aluno-curso","Curso publicado não bloqueado, professor ativo, ao menos uma aula publicada READY, todas as aulas concluídas e cada avaliação obrigatória aprovada SUBMITTED. Soma pares distintos, não pessoas nem certificados.","Mês da data derivada: maior horário entre última aula e primeira aprovação de cada avaliação obrigatória. Situação atual do currículo, não registro histórico imutável de certificação. Apenas eventos após consentimento.","UF autodeclarada no consentimento; nenhum município inferido.","Pelo menos dez contas de aluno distintas no próprio indicador/mês; faixa de dez."),
 metric("VERIFIED_AWARDS","registros de competência educacional","COUNT de conquistas com tentativa submetida/aprovada consistente (aluno, avaliação, nota), não revogadas e ainda válidas. Exclui autodeclarações e resultados profissionais de empresas.","Mês de awarded_at; somente posterior ao consentimento vigente.","UF do consentimento.","Dez contas de aluno distintas, faixa de dez. Uma pessoa com muitas conquistas não supera o limiar.")
 ),"privacyNotice","Supressão e faixas reduzem exposição; não constituem prova formal de anonimização nem privacidade diferencial.");}
}
